borrower = None
try:
    borrower = query_borrower({"name": inputs["borrower_name"]})
except Exception:
    borrower = None

transactions = []
if borrower and borrower.get("borrower_id"):
    raw = query_transactions({"borrower_id": borrower["borrower_id"], "limit": 1000})
    if raw:
        start = inputs["start_date"]
        end = inputs["end_date"]
        transactions = [t for t in raw if t.get("date") and start <= t["date"] <= end]
        transactions = sorted(transactions, key=lambda t: t["date"])

result = {"borrower": borrower, "transactions": transactions}

payments = query_payments({"loan_id": inputs["loan_id"]})

totals = {}
for payment in payments:
    method = payment.get("method")
    amount = payment.get("amount")
    if method is None or amount is None:
        continue
    try:
        amount_value = float(amount)
    except (TypeError, ValueError):
        continue
    totals[method] = totals.get(method, 0.0) + amount_value

result = {method: round(total, 2) for method, total in totals.items()}

def _parse_cities(raw):
    if raw is None:
        return []
    return [c.strip() for c in str(raw).split(",") if c.strip()]


def _get_npl_ratio(city):
    summary = query_portfolio_summary({"city": city})
    if not isinstance(summary, dict):
        return 0.0
    val = summary.get("npl_ratio")
    if val is None:
        return 0.0
    try:
        return float(val)
    except (TypeError, ValueError):
        return 0.0


cities = _parse_cities(inputs.get("cities"))

city_ratios = {}
for city in cities:
    city_ratios[city] = _get_npl_ratio(city)

sorted_cities = sorted(city_ratios.keys(), key=lambda c: (-city_ratios[c], c))

result = {city: city_ratios[city] for city in sorted_cities}

stats = query_delinquency_stats({"bucket": None})
if stats is None:
    stats = []
rows = []
for s in stats:
    rows.append({
        "bucket": s.get("bucket"),
        "recovery_rate": s.get("recovery_rate", 0) if s.get("recovery_rate") is not None else 0,
    })
rows.sort(key=lambda r: r["recovery_rate"])
result = rows

def _bid(b):
    if "borrower_id" in b and b["borrower_id"] is not None:
        return b["borrower_id"]
    return b.get("id")


def _amt(g):
    v = g.get("guarantee_amount")
    if v is None:
        return 0
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0


def _run():
    city = inputs.get("city")
    top_n = inputs.get("top_n", 5)
    try:
        top_n = int(top_n)
    except (TypeError, ValueError):
        top_n = 5

    borrowers = query_borrowers_by_city({"city": city, "limit": 5}) or []

    totals = {}
    counts = {}
    for b in borrowers:
        bid = _bid(b)
        if bid is None:
            continue
        guarantors = query_guarantors({"borrower_id": bid}) or []
        seen_names_this_borrower = set()
        for g in guarantors:
            name = g.get("name")
            if name is None:
                continue
            totals[name] = totals.get(name, 0.0) + _amt(g)
            if name not in seen_names_this_borrower:
                seen_names_this_borrower.add(name)
                counts[name] = counts.get(name, 0) + 1

    ranked = sorted(totals.items(), key=lambda kv: kv[1], reverse=True)

    out = []
    for name, total in ranked[:top_n]:
        out.append({
            "name": name,
            "total_guarantee_amount": total,
            "borrower_count": counts.get(name, 0),
        })
    return out


result = _run()

borrowers = query_borrowers_by_city({"city": inputs["city"]})

result = []
for borrower in borrowers:
    loans = query_loans({"borrower_id": borrower["borrower_id"]})
    for loan in loans:
        if loan.get("status") != "defaulted":
            continue
        collateral = query_collateral({"loan_id": loan["loan_id"]})
        total = 0
        for c in collateral:
            value = c.get("appraised_value")
            if isinstance(value, (int, float)):
                total += value
        if total > loan.get("amount", 0):
            enriched = dict(loan)
            enriched["collateral"] = collateral
            enriched["collateral_total"] = total
            result.append(enriched)

def _get_borrower(name):
    if not name:
        return None
    b = query_borrower({"name": name})
    if not b:
        return None
    return b


def _get_loans(borrower_id):
    if not borrower_id:
        return []
    loans = query_loans({"borrower_id": borrower_id})
    if not loans:
        return []
    return loans


def _get_payments(loan_id):
    if not loan_id:
        return []
    payments = query_payments({"loan_id": loan_id})
    if not payments:
        return []
    return payments


def _build_result(brwr_name):
    borrower = _get_borrower(brwr_name)
    if not borrower:
        return {}
    borrower_id = borrower.get("borrower_id")
    loans = _get_loans(borrower_id)
    if not loans:
        return {}

    totals = {}
    completed = {}

    for loan in loans:
        loan_id = loan.get("loan_id") if isinstance(loan, dict) else None
        payments = _get_payments(loan_id)
        for p in payments:
            if not isinstance(p, dict):
                continue
            method = p.get("method")
            if method is None:
                method = ""
            method = str(method)
            totals[method] = totals.get(method, 0) + 1
            if str(p.get("status")) == "completed":
                completed[method] = completed.get(method, 0) + 1

    output = {}
    for method, total in totals.items():
        if total > 0:
            output[method] = completed.get(method, 0) / total
        else:
            output[method] = 0.0
    return output


result = _build_result(inputs.get("borrower_name"))

city_list = [c.strip() for c in inputs["cities"].split(",") if c.strip()]

per_city_averages = {}
all_scores = []
all_incomes = []

for city in city_list:
    borrowers = query_borrowers_by_city({"city": city, "limit": 100})
    if not borrowers:
        per_city_averages[city] = None
        continue
    scores = [b.get("credit_score") for b in borrowers if b.get("credit_score") is not None]
    if scores:
        per_city_averages[city] = sum(scores) / len(scores)
    else:
        per_city_averages[city] = None
    for b in borrowers:
        cs = b.get("credit_score")
        mi = b.get("monthly_income")
        if cs is not None and mi is not None:
            all_scores.append(cs)
            all_incomes.append(mi)

if len(all_scores) >= 2 and len(all_scores) == len(all_incomes):
    correlation = compute_correlation({"x_values": all_scores, "y_values": all_incomes})
else:
    correlation = {"error": "insufficient data", "n": len(all_scores)}

result = {
    "per_city_averages": per_city_averages,
    "correlation": correlation,
}

borrowers = query_borrowers_by_city({"city": inputs["city"], "limit": inputs["limit"]})

active_statuses = {"active", "current", "open"}

def get_amount(loan):
    if not isinstance(loan, dict):
        return 0.0
    val = loan.get("amount", 0)
    if val is None:
        return 0.0
    try:
        return float(val)
    except (TypeError, ValueError):
        return 0.0

def status_of(loan):
    if not isinstance(loan, dict):
        return ""
    s = loan.get("status", "")
    if s is None:
        return ""
    return str(s).strip().lower()

def is_active(loan):
    s = status_of(loan)
    if s == "":
        return True
    return s in active_statuses

out = []
if not isinstance(borrowers, list):
    borrowers = []

for b in borrowers:
    if not isinstance(b, dict):
        continue
    bid = b.get("borrower_id")
    loans = query_loans({"borrower_id": bid}) if bid is not None else []
    if not isinstance(loans, list):
        loans = []
    total_debt = 0.0
    for loan in loans:
        if is_active(loan):
            total_debt += get_amount(loan)

    income = b.get("monthly_income", 0)
    try:
        income = float(income)
    except (TypeError, ValueError):
        income = 0.0

    if income > 0:
        ratio = total_debt / income
    else:
        ratio = 0.0

    out.append({
        "borrower_id": bid,
        "name": b.get("name"),
        "city": b.get("city"),
        "credit_score": b.get("credit_score"),
        "monthly_income": income,
        "total_loans": b.get("total_loans"),
        "total_outstanding": b.get("total_outstanding"),
        "total_debt": total_debt,
        "debt_to_income_ratio": ratio,
    })

out.sort(key=lambda x: x["debt_to_income_ratio"], reverse=True)
result = out

