success_outcomes = ('promise_to_pay', 'partial_payment', 'paid_in_full')

monthly = {}
for rec in records:
    action_date = rec.get("action_date")
    if not action_date:
        continue
    month = action_date[:7]
    bucket = monthly.get(month)
    if bucket is None:
        bucket = {"month": month, "total_actions": 0, "success_count": 0}
        monthly[month] = bucket
    bucket["total_actions"] += 1
    if rec.get("outcome") in success_outcomes:
        bucket["success_count"] += 1

result = []
for month in sorted(monthly.keys()):
    bucket = monthly[month]
    total = bucket["total_actions"]
    success = bucket["success_count"]
    rate = (success / total) if total > 0 else 0.0
    result.append({
        "month": month,
        "total_actions": total,
        "success_count": success,
        "effectiveness_rate": rate,
    })

def _to_num(x):
    try:
        return float(x)
    except (TypeError, ValueError):
        return 0.0

city = inputs["city"]
borrowers = query_borrowers_by_city({"city": city, "limit": 10}) or []

product_totals = {}
seen = set()

for b in borrowers:
    bid = b.get("borrower_id") if isinstance(b, dict) else None
    if not bid or bid in seen:
