borrowers = query_borrowers_by_city({"city": city, "limit": 5})
product_sums = {}
product_counts = {}
for borrower in borrowers:
    loans = query_loans({"borrower_id": borrower["borrower_id"]})
    for loan in loans:
        amount = loan.get("amount")
        if amount is None or amount == 0:
            continue
        product = loan.get("product")
        if product is None:
            continue
        collaterals = query_collateral({"loan_id": loan["loan_id"]})
        total_collateral_value = 0
        for collateral in collaterals:
            value = collateral.get("appraised_value")
            if value is not None:
