        coverage = total_collateral_value / amount
        product_sums[product] = product_sums.get(product, 0) + coverage
        product_counts[product] = product_counts.get(product, 0) + 1
result = {}
for product in product_sums:
    result[product] = product_sums[product] / product_counts[product]

def _get(d, key, default=None):
    try:
        v = d.get(key, default)
    except Exception:
        return default
    return default if v is None else v


def _num(v):
    try:
        return float(v)
    except Exception:
        return 0.0


borrowers = query_borrowers_by_city({
    "city": inputs["city"],
    "limit": inputs.get("borrower_limit", 10),
})
if not isinstance(borrowers, list):
    borrowers = []

collected = []
for b in borrowers:
    bid = _get(b, "borrower_id")
    if bid is None:
        continue
    loans = query_loans({"borrower_id": bid})
    if not isinstance(loans, list):
        continue
    for loan in loans:
        status = _get(loan, "status")
        if status != "active":
            continue
        amount = _num(_get(loan, "amount"))
        rate = _num(_get(loan, "interest_rate"))
        tenor = _num(_get(loan, "tenor_months"))
        interest_earned = amount * rate / 100 * tenor / 12
        collected.append({
            "loan_id": _get(loan, "loan_id"),
            "amount": amount,
            "interest_rate": rate,
            "interest_earned": interest_earned,
        })

collected.sort(key=lambda x: x["interest_earned"], reverse=True)

top_n_raw = inputs.get("top_n", 10)
try:
