borrower_id = None
if borrower:
    borrower_id = borrower.get("borrower_id")

loans = []
if borrower_id:
    loans = query_loans({"borrower_id": borrower_id})

result = {"active": 0, "paid_off": 0, "defaulted": 0, "restructured": 0}

for loan in loans or []:
