    "total_loans": summary.get("total_loans", 0),
    "avg_loan_amount": summary.get("avg_loan_amount", 0),
    "npl_ratio": summary.get("npl_ratio", 0),
}

def _extract(rows):
    out = []
    if rows is None:
        return out
    if isinstance(rows, dict):
        for k, v in rows.items():
            if isinstance(v, dict):
                cnt = v.get("loan_count", 0)
                bname = v.get("bucket", k)
            else:
                cnt = v
                bname = k
            try:
                cnt = int(cnt) if cnt is not None else 0
            except (TypeError, ValueError):
                cnt = 0
            out.append({"bucket": bname, "loan_count": cnt})
        return out
    for row in rows:
        if isinstance(row, dict):
            bname = row.get("bucket")
            if bname is None:
                bname = row.get("name")
            cnt = row.get("loan_count", 0)
            try:
                cnt = int(cnt) if cnt is not None else 0
            except (TypeError, ValueError):
                cnt = 0
            out.append({"bucket": bname, "loan_count": cnt})
        else:
            out.append({"bucket": None, "loan_count": 0})
    return out


raw = query_delinquency_stats({"bucket": None})
stats = _extract(raw)
stats.sort(key=lambda r: r["loan_count"], reverse=True)
result = stats

payments = query_payments({"loan_id": inputs["loan_id"]})
status = inputs["payment_status"]
matched = [p for p in payments if p.get("status") == status]
