def _status_defaulted(status):
    if status is None:
        return False
    return str(status).strip().lower() == "defaulted"


def _dpd_value(loan):
    if loan is None:
        return 0
    dpd = loan.get("dpd")
    if dpd is None:
        return 0
    try:
        return float(dpd)
    except (TypeError, ValueError):
        return 0


def _categorize(loans):
    if not loans:
        return "low_risk"
    any_defaulted = False
    max_dpd = 0
    for loan in loans:
        if _status_defaulted(loan.get("status")):
            any_defaulted = True
        d = _dpd_value(loan)
        if d > max_dpd:
            max_dpd = d
    if any_defaulted or max_dpd > 90:
        return "high_risk"
    if max_dpd > 30:
        return "medium_risk"
    return "low_risk"


