metric = inputs.get('metric') or 'interest_rate'
if metric not in ('interest_rate', 'loan_amount'):
    metric = 'interest_rate'
metric_field = 'amount' if metric == 'loan_amount' else 'interest_rate'

group_by = inputs.get('group_by') or 'product_type'
group_field = 'product' if group_by in ('product_type', 'product', None) else group_by

if not cities:
    result = {
        'table': [],
        'summary_text': 'Error: no cities provided. Please supply a comma-separated list of cities.',
        'per_city': {},
        'summary': {'metric': metric, 'group_by': group_by, 'cities': [], 'products': []},
    }
else:
    per_city = {}
    for city in cities:
        borrowers = query_borrowers_by_city({'city': city, 'limit': 1000}) or []
        agg = {}
        for borrower in borrowers:
            bid = borrower.get('borrower_id') or borrower.get('id')
            if not bid:
                continue
            loans = query_loans({'borrower_id': bid}) or []
            for loan in loans:
                product = loan.get(group_field) or loan.get('product') or 'UNKNOWN'
                raw_val = loan.get(metric_field)
                if raw_val is None:
                    continue
                try:
                    val = float(raw_val)
                except (TypeError, ValueError):
                    continue
                entry = agg.get(product)
                if entry is None:
                    entry = {'total': 0.0, 'count': 0}
                    agg[product] = entry
                entry['total'] += val
                entry['count'] += 1
        city_summary = {}
        for product, entry in agg.items():
            cnt = entry['count']
            city_summary[product] = {
                'avg': round(entry['total'] / cnt, 4) if cnt else None,
                'count': cnt,
            }
        per_city[city] = city_summary

    products = []
    seen = set()
    for city in cities:
        for product in per_city.get(city, {}):
            if product not in seen:
                seen.add(product)
                products.append(product)

    city_avg_cols = [f'{c}_avg' for c in cities]
    city_cnt_cols = [f'{c}_count' for c in cities]
    columns = [group_by] + city_avg_cols + city_cnt_cols + ['higher_city']

    table_records = []
    for product in products:
        row = {group_by: product}
        city_vals = {}
        for city in cities:
            info = per_city.get(city, {}).get(product)
            if info and info['avg'] is not None:
                row[f'{city}_avg'] = info['avg']
                row[f'{city}_count'] = info['count']
                city_vals[city] = info['avg']
            else:
                row[f'{city}_avg'] = None
                row[f'{city}_count'] = 0
        if city_vals:
            top_city = max(city_vals, key=lambda c: city_vals[c])
            row['higher_city'] = top_city
        else:
            row['higher_city'] = None
        table_records.append(row)

    tabulated = tabulate_data({'records': table_records, 'columns': columns, 'sort_by': group_by, 'ascending': True})
    table = tabulated if isinstance(tabulated, list) else table_records

    summary_lines = []
    for product in products:
        vals = {}
        for city in cities:
            info = per_city.get(city, {}).get(product)
            if info and info['avg'] is not None:
                vals[city] = info['avg']
        missing = [c for c in cities if c not in vals]
        if not vals:
            summary_lines.append(f"{product}: no data available in any selected city.")
            continue
        top_city = max(vals, key=lambda c: vals[c])
        if len(vals) > 1:
            line = f"{product}: {top_city} has the highest average {metric} ({vals[top_city]})"
            line += " vs " + ", ".join(f"{c}={vals[c]}" for c in cities if c in vals and c != top_city) + "."
        else:
            line = f"{product}: only {top_city} has data, average {metric} = {vals[top_city]}."
        if missing:
            line += " Missing in " + ", ".join(missing) + "."
        summary_lines.append(line)

    summary_text = " ".join(summary_lines) if summary_lines else "No loans found for the selected cities."

    summary = {
        'metric': metric,
        'group_by': group_by,
        'cities': cities,
        'products': products,
    }

    result = {
        'table': table,
        'summary_text': summary_text,
        'per_city': per_city,
        'summary': summary,
    }
